const {spawn} = require('child_process');
const np = require('/tmp/rev8/np_ranges.json');
function printable(cp){ let lo=0,hi=np.length-1; while(lo<=hi){const m=(lo+hi)>>1; if(cp<np[m][0])hi=m-1; else if(cp>np[m][1])lo=m+1; else return false;} return true; }
function hx(n,w){return n.toString(16).padStart(w,'0');}
function pyrepr(s){
  const chars = Array.from(s);
  let quote = "'";
  if (s.includes("'") && !s.includes('"')) quote = '"';
  let out = quote;
  for (const ch of chars){
    const cp = ch.codePointAt(0);
    if (ch === quote || ch === '\\') out += '\\' + ch;
    else if (ch === '\t') out += '\\t';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (cp < 0x20 || cp === 0x7f) out += '\\x' + hx(cp,2);
    else if (cp < 0x7f) out += ch;
    else if (!printable(cp)) {
      if (cp <= 0xff) out += '\\x'+hx(cp,2);
      else if (cp <= 0xffff) out += '\\u'+hx(cp,4);
      else out += '\\U'+hx(cp,8);
    } else out += ch;
  }
  return out + quote;
}
function unot(cp){return 'U+'+cp.toString(16).toUpperCase().padStart(4,'0');}
function run(domain){return new Promise(res=>{
  const p = spawn('/workspace/dataset/test8_executable',['--domain',domain,'--mode','encode'],{stdio:['ignore','pipe','ignore']});
